import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {format} from 'date-fns'

import {DATE_FORMAT} from '../LicensesPage.consts'
import {getEntityLicensesCount} from '../LicensesPage.utils'

import AgentsLicensesInformation from './AgentsLicensesInformation/AgentsLicensesInformation'
import ExpirationAlert from './ExpirationAlert/ExpirationAlert'
import LicenseActions from './LicenseActions/LicenseActions'
import {LICENSING_POLICY_DOC_LINK} from './LicenseInformation.consts'
import {useLicenseInformation} from './LicenseInformation.hooks'
import {getMaintenanceExpirationText} from './LicenseInformation.utils'

import styles from './LicenseInformation.module.css'

import {AlertType} from 'src/components/common/Alert/Alert'
import Badge from 'src/components/common/Badge/Badge'
import HelpDetails from 'src/components/common/HelpDetails/HelpDetails'

function LicenseInformation() {
  const {
    readOnly,
    teamLink,
    isJWTLicense,
    licenseId,
    licenseMode,
    originalLicenseMode,
    isLicenseModeChanged,
    currentDisplayVersion,
    effectiveReleaseDate,
    licensedAgentsCount,
    licensedBuildTypesCount,
    licensedPipelinesCount,
    maintenanceDueDate,
    isMaintenanceExpired,
    isObsolete,
    expirationDate,
    isExpired,
    expiringMessage,
    shouldShowExpirationWarning,
    shouldShowMaintenanceExpirationWarning,
    shouldShowAgentLicenses,
    agentLicenses,
    hasExpiringAgentLicenses,
    hasKnownUpgradeVersions,
    isNotCompatibleWithLatestVersion,
  } = useLicenseInformation()

  return (
    <>
      {shouldShowExpirationWarning && (
        <ExpirationAlert
          renewalLink={teamLink}
          renewalButtonText={'Upgrade to TeamCity Enterprise'}
          type={isExpired ? AlertType.ERROR : AlertType.WARNING}
        >
          {`Your TeamCity Enterprise Trial license ${isExpired ? 'is expired' : expiringMessage}. ` +
            'Upgrade to Enterprise license now to maintain access to unlimited build ' +
            'configurations, priority support, and additional benefits.'}
        </ExpirationAlert>
      )}
      {shouldShowMaintenanceExpirationWarning && (
        <ExpirationAlert renewalLink={teamLink}>
          {getMaintenanceExpirationText(hasExpiringAgentLicenses, hasKnownUpgradeVersions)}
        </ExpirationAlert>
      )}
      <div className={styles.badges}>
        {currentDisplayVersion != null && effectiveReleaseDate != null && (
          <div className={styles.versionInfo}>
            {`Current version: ${currentDisplayVersion}, effective release date ${format(effectiveReleaseDate, DATE_FORMAT)}`}
          </div>
        )}
        <Badge label={'Current license'}>
          {isLicenseModeChanged && (
            <span className={styles.originalLicense}>{`TeamCity ${originalLicenseMode}`}</span>
          )}
          <span className={styles.value}>{`TeamCity ${licenseMode}`}</span>
          <HelpDetails>
            {
              'JetBrains offers several licensing options that allow you to scale TeamCity according to your needs.'
            }
            <Link
              className={styles.learnMore}
              href={LICENSING_POLICY_DOC_LINK}
              target="_blank"
              rel="noreferrer"
            >
              {'Learn more'}
            </Link>
          </HelpDetails>
        </Badge>
        {licenseId && (
          <Badge label={'License ID'}>
            <span className={styles.value}>{licenseId}</span>
          </Badge>
        )}
        {maintenanceDueDate != null && expirationDate == null && (
          <Badge label={'End of maintenance'}>
            {(isNotCompatibleWithLatestVersion || isMaintenanceExpired || isObsolete) && (
              <SvgIcon
                icon={isObsolete ? 'exception' : 'warning'}
                className={classNames(styles.icon, isObsolete ? styles.error : styles.warning)}
                title={
                  !isObsolete && isNotCompatibleWithLatestVersion
                    ? 'Your license needs to be renewed before upgrading to the latest version'
                    : 'Your license maintenance is expired'
                }
              />
            )}
            <span
              className={classNames(styles.value, {
                [styles.error]: isObsolete,
              })}
            >
              {format(maintenanceDueDate, DATE_FORMAT)}
            </span>
          </Badge>
        )}
        {expirationDate != null && (
          <Badge label={'Expires on'}>
            {shouldShowExpirationWarning && (
              <SvgIcon
                icon={isExpired ? 'exception' : 'warning'}
                className={classNames(styles.icon, isExpired ? styles.error : styles.warning)}
                title={`Your license ${isExpired ? 'is expired' : 'is expiring soon'}`}
              />
            )}
            <span
              className={classNames(styles.value, {
                [styles.error]: isExpired,
              })}
            >
              {format(expirationDate, DATE_FORMAT)}
            </span>
          </Badge>
        )}
        <Badge label={'Build configurations'}>
          <span className={styles.value}>{getEntityLicensesCount(licensedBuildTypesCount)}</span>
        </Badge>
        <Badge label={'Pipelines'}>
          <span className={styles.value}>{getEntityLicensesCount(licensedPipelinesCount)}</span>
        </Badge>
        <Badge label={'Build agents'}>
          <span className={styles.value}>{getEntityLicensesCount(licensedAgentsCount)}</span>
        </Badge>
        {isJWTLicense && !readOnly && <LicenseActions />}
      </div>
      {isJWTLicense && shouldShowAgentLicenses && (
        <AgentsLicensesInformation
          active={agentLicenses.active}
          expiring={agentLicenses.expiring}
          inactive={agentLicenses.inactive}
          hasKnownUpgradeVersions={hasKnownUpgradeVersions}
          showExpirationWarning={
            hasExpiringAgentLicenses && !shouldShowMaintenanceExpirationWarning
          }
        />
      )}
    </>
  )
}

export default LicenseInformation
