export enum LicenseMode {
  PROFESSIONAL = 'Professional',
  ENTERPRISE = 'Enterprise',
  TRIAL = 'Enterprise Trial',
  OPEN_SOURCE = 'Open Source',
  TRUE_UP = 'True-Up',
}

export enum LicenseType {
  ENTERPRISE_COM = 5,
  ENTERPRISE_TRIAL = 6,
  JWT_EXPIRED_ENTERPRISE = 14,
}

export type AvailableVersion = {
  version: string
  releaseDate: number
}

type JWTLicense = {
  keyData: {
    licenseId: string
    licenseType: LicenseType
    originalLicenseDescription: LicenseMode
    truncatedAgentsUpgradeDueDate: Record<string, number>
    maintenanceDueDate: number
    expirationDate: number | null
    licenseExpired: boolean
  } | null
  validateError: string | null
  obsolete: boolean
  valid: boolean
}

export type LicenseData = {
  licensedAgentsCount: number
  licensedBuildTypesCount: number
  licensedPipelinesCount: number
  licenseMode: LicenseMode
  activationLink: string | null
  deactivationLink: string | null
  jwtLicense: JWTLicense | null
  lastUpdateTime: number
  lastUpdateError: string | null
  currentDisplayVersion: string
  releaseDate: number
  availableVersions: AvailableVersion[]
  readOnly: boolean
  teamLink: string | null
}

export type LegacyLicenseData = {
  key: string
  type: string
  agentsCount: number
  buildTypesCount: number
  pipelinesCount: number
  generationDate: number
  maintenanceDueDate: number
  expirationDate: number | null
  maintenanceExpiringSoon: boolean
  expired: boolean
  obsolete: boolean
  expiringSoon: boolean
  maintenanceExpired: boolean
  active: boolean
  valid: boolean
}

export type LegacyLicenseDataWithNotCompatibleVersions = LegacyLicenseData & {
  notCompatibleVersions: AvailableVersion[]
}
