export function getHiddenLicenseKey(licenseKey: string) {
  const segments = licenseKey.split('-').map((segment, i, splitted) => {
    if (i === 0 || i === splitted.length - 1) {
      return segment
    }
    return segment.replace(/./g, '∗')
  })

  return segments.join('-')
}

export function getShortenedLicenseKey(licenseKey: string) {
  const splitted = licenseKey.split('-')
  return `∗∗∗∗∗-${splitted[splitted.length - 1]}`
}
