import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useState} from 'react'

import type {LegacyLicenseData} from '../../LicensesPage.types'
import {useLicenseKeysSelection} from '../LegacyLicenses.hooks'
import LegacyLicensesActions from '../LegacyLicensesActions/LegacyLicensesActions'

import InactiveLegacyLicense from './InactiveLegacyLicense'

import styles from './InactiveLegacyLicenses.module.css'

type Props = {
  licenses: LegacyLicenseData[]
  readOnly?: boolean
}

function InactiveLegacyLicenses({licenses, readOnly}: Props) {
  const [isExpanded, setIsExpanded] = useState(false)
  const {selectedKeys, clearSelectedKeys, toggleSelectKey, toggleSelectAllKeys} =
    useLicenseKeysSelection(licenses)

  return (
    <div className={styles.inactiveKeys}>
      <H2 className={styles.heading}>
        <IconButton
          className={styles.toggle}
          title={`${isExpanded ? 'Collapse' : 'Expand'} inactive license keys`}
          icon={isExpanded ? 'chevron-down' : 'chevron-right'}
          onClick={() => setIsExpanded(prevState => !prevState)}
        >
          {'Inactive license keys'}
        </IconButton>
      </H2>
      {isExpanded && (
        <>
          <table className={classNames(styles.licenseKeysTable, {[styles.readOnly]: readOnly})}>
            <thead>
              <tr>
                <th>{'License key'}</th>
                <th>{'Description'}</th>
                {!readOnly && (
                  <th>
                    <Checkbox
                      containerClassName={styles.checkbox}
                      checked={selectedKeys.size === licenses.length}
                      onChange={toggleSelectAllKeys}
                    />
                  </th>
                )}
              </tr>
            </thead>
            <tbody>
              {licenses.map(license => (
                <InactiveLegacyLicense
                  key={license.key}
                  license={license}
                  onSelect={toggleSelectKey}
                  readOnly={readOnly}
                  checked={selectedKeys.has(license.key)}
                />
              ))}
            </tbody>
          </table>
          <LegacyLicensesActions
            selectedKeys={selectedKeys}
            onRemovalSuccess={clearSelectedKeys}
            readOnly={readOnly}
            removalOnly
          />
        </>
      )}
    </div>
  )
}

export default InactiveLegacyLicenses
