import {format} from 'date-fns'

import licensesPageApi from './LicensesPage.api'
import {DATE_FORMAT} from './LicensesPage.consts'
import {LicenseType} from './LicensesPage.types'
import {isLicenseActive} from './LicensesPage.utils'

export function useLicenseMaintenance() {
  const {keyData, licenseMode, effectiveReleaseDate} =
    licensesPageApi.endpoints.getLicenseData.useQueryState(undefined, {
      selectFromResult: ({data}) => ({
        keyData: data?.jwtLicense?.keyData,
        licenseMode: data?.licenseMode,
        effectiveReleaseDate: data?.releaseDate,
      }),
    })
  const {
    licenseType,
    maintenanceDueDate,
    originalLicenseDescription: originalLicenseMode,
  } = keyData ?? {}
  const obsoleteLicenseMessage = `The currently used key is not compatible with this TeamCity version.
  The maintenance period for this license expired before this server version was released${
    maintenanceDueDate != null && effectiveReleaseDate != null
      ? ` (license expired on ${format(maintenanceDueDate, DATE_FORMAT)}, server effective release date is ${format(effectiveReleaseDate, DATE_FORMAT)})`
      : ''
  }.`

  return {
    licenseMode,
    originalLicenseMode,
    obsoleteLicenseMessage,
    isObsolete: licenseType === LicenseType.JWT_EXPIRED_ENTERPRISE,
    isMaintenanceExpired:
      maintenanceDueDate != null && !isLicenseActive(maintenanceDueDate, new Date()),
  }
}
