import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {memo} from 'react'

import ExpirationAlert from '../ExpirationAlert/ExpirationAlert'
import {UPDATES_PAGE_LINK} from '../LicenseInformation.consts'
import type {
  ActiveAgentLicenses,
  ExpiringAgentLicenses,
  InactiveAgentLicenses,
} from '../LicenseInformation.types'

import {BUY_AGENTS_LINK} from './AgentsLicensesInformation.consts'
import {useAgentsLicensesInformation} from './AgentsLicensesInformation.hooks'
import AgentsLicensesTable from './AgentsLicensesTable/AgentsLicensesTable'
import InactiveAgentsLicenses from './InactiveAgentsLicenses/InactiveAgentsLicenses'

import styles from './AgentsLicensesInformation.module.css'

type Props = {
  active: ActiveAgentLicenses
  expiring: ExpiringAgentLicenses
  inactive: InactiveAgentLicenses
  showExpirationWarning?: boolean
  hasKnownUpgradeVersions?: boolean
}
function AgentsLicensesInformation({
  active,
  expiring,
  inactive,
  showExpirationWarning,
  hasKnownUpgradeVersions,
}: Props) {
  const {teamLink, areAgentsUnlimited} = useAgentsLicensesInformation()

  return (
    <div className={styles.licenses}>
      <div className={styles.header}>
        <H2 className={styles.title}>{'Agent licenses'}</H2>
        <div>
          {!areAgentsUnlimited &&
            'To increase the number of build agents, click "Get more" and purchase additional agent licenses. '}
          {'If your JetBrains account has multiple teams and you’ve purchased a paid agent license, ' +
            'ensure this license belongs to the same team that owns the TeamCity server license.'}
        </div>
        <div className={styles.links}>
          {!areAgentsUnlimited && (
            <IconButton
              className={styles.link}
              href={BUY_AGENTS_LINK}
              icon="new-window"
              target="_blank"
              rel="noreferrer"
              primary
            >
              {'Get more'}
            </IconButton>
          )}
          {teamLink != null && (
            <IconButton
              className={styles.link}
              href={teamLink}
              icon="new-window"
              target="_blank"
              rel="noreferrer"
              primary
            >
              {'Manage your licenses'}
            </IconButton>
          )}
        </div>
      </div>
      {expiring.length > 0 && (
        <>
          {showExpirationWarning && (
            <ExpirationAlert renewalLink={teamLink}>
              <div>
                {hasKnownUpgradeVersions ? (
                  <>
                    {'Agent licenses that display the warning icon do not support '}
                    <Link href={UPDATES_PAGE_LINK}>{'the latest version'}</Link>
                    {' of TeamCity server. Updating your server'}
                  </>
                ) : (
                  'The maintenance period for agent licenses has ended. Updating your server to newer major TeamCity releases'
                )}
                {
                  ' will reduce the number of authorized agents. Renew the agent licenses to maintain your agent count while benefiting from the latest server updates.'
                }
              </div>
            </ExpirationAlert>
          )}
          <AgentsLicensesTable
            title={'Active expiring licenses'}
            agentLicenses={expiring}
            withSupportedVersions
          />
        </>
      )}
      {active.length > 0 && (
        <AgentsLicensesTable title={'Active licenses'} agentLicenses={active} />
      )}
      {inactive.length > 0 && <InactiveAgentsLicenses agentLicenses={inactive} />}
    </div>
  )
}

export default memo(AgentsLicensesInformation)
