import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import type React from 'react'

import styles from './ExpirationAlert.module.css'

import Alert, {AlertType} from 'src/components/common/Alert/Alert'

type Props = {
  renewalLink?: string | null
  renewalButtonText?: string
  type?: AlertType
  children: React.ReactNode
}
function ExpirationAlert({
  renewalLink,
  renewalButtonText = 'Go to renewal',
  type = AlertType.WARNING,
  children,
}: Props) {
  return (
    <Alert contentClassName={styles.alert} type={type}>
      {children}
      {renewalLink != null && (
        <IconButton
          className={styles.link}
          href={renewalLink}
          icon="new-window"
          target="_blank"
          rel="noreferrer"
          primary
        >
          {renewalButtonText}
        </IconButton>
      )}
    </Alert>
  )
}

export default ExpirationAlert
