import {compareAsc, differenceInCalendarDays, parseISO} from 'date-fns'
import plur from 'plur'
import {useMemo} from 'react'

import licensesPageApi from '../LicensesPage.api'
import {UNLIMITED_AGENTS_KEY} from '../LicensesPage.consts'
import {useLicenseMaintenance} from '../LicensesPage.hooks'
import {LicenseMode} from '../LicensesPage.types'
import {
  getLastSupportedVersion,
  isLicenseActive,
  isLicenseNotCompatibleWithVersion,
} from '../LicensesPage.utils'

import {EXPIRATION_THRESHOLD} from './LicenseInformation.consts'
import type {
  ActiveAgentLicenses,
  AgentLicense,
  ExpiringAgentLicenses,
  InactiveAgentLicenses,
} from './LicenseInformation.types'

function getVersionNumber(displayVersion?: string) {
  return displayVersion?.split(' ')[0].split('.').slice(0, 2).join('.')
}

function getLicenseComparator(asc = true) {
  return (l1: AgentLicense, l2: AgentLicense) => {
    if (l1[0] === UNLIMITED_AGENTS_KEY) {
      return 1
    }
    if (l2[0] === UNLIMITED_AGENTS_KEY) {
      return -1
    }
    return asc ? compareAsc(l1[0], l2[0]) : compareAsc(l2[0], l1[0])
  }
}
const licenseComparatorAsc = getLicenseComparator()
const licenseComparatorDesc = getLicenseComparator(false)

export function useLicenseInformation() {
  const {
    readOnly,
    teamLink,
    jwtLicense,
    effectiveReleaseDate,
    availableVersions,
    currentVersion,
    currentDisplayVersion,
    licensedAgentsCount,
    licensedBuildTypesCount,
    licensedPipelinesCount,
  } = licensesPageApi.endpoints.getLicenseData.useQueryState(undefined, {
    selectFromResult: ({data}) => ({
      readOnly: data?.readOnly,
      teamLink: data?.teamLink,
      jwtLicense: data?.jwtLicense,
      licensedAgentsCount: data?.licensedAgentsCount,
      currentDisplayVersion: data?.currentDisplayVersion,
      licensedBuildTypesCount: data?.licensedBuildTypesCount,
      licensedPipelinesCount: data?.licensedPipelinesCount,
      effectiveReleaseDate: data?.releaseDate,
      availableVersions: data?.availableVersions,
      currentVersion: getVersionNumber(data?.currentDisplayVersion),
    }),
  })
  const {
    licenseId,
    maintenanceDueDate,
    expirationDate,
    truncatedAgentsUpgradeDueDate,
    licenseExpired: isExpired,
  } = jwtLicense?.keyData ?? {}
  const {licenseMode, originalLicenseMode, isObsolete, isMaintenanceExpired} =
    useLicenseMaintenance()
  const expiresInDays =
    expirationDate != null ? differenceInCalendarDays(expirationDate, new Date()) : null
  const isExpiring = expiresInDays != null && expiresInDays <= EXPIRATION_THRESHOLD
  const expiringMessage = isExpiring
    ? expiresInDays === 0
      ? 'expires today'
      : `expires in ${expiresInDays} ${plur('day', expiresInDays)}`
    : ''
  const shouldShowExpirationWarning = isExpiring || isExpired

  const hasKnownUpgradeVersions = availableVersions != null && availableVersions.length > 0
  const isNotCompatibleWithLatestVersion =
    maintenanceDueDate != null &&
    hasKnownUpgradeVersions &&
    isLicenseNotCompatibleWithVersion(maintenanceDueDate, availableVersions[0])

  const shouldShowAgentLicenses =
    licenseMode !== LicenseMode.OPEN_SOURCE && licenseMode !== LicenseMode.TRUE_UP

  const agentLicenses = useMemo(() => {
    const active: ActiveAgentLicenses = []
    const expiring: ExpiringAgentLicenses = []
    const inactive: InactiveAgentLicenses = []
    const result = {
      active,
      expiring,
      inactive,
    }

    if (
      !shouldShowAgentLicenses ||
      truncatedAgentsUpgradeDueDate == null ||
      effectiveReleaseDate == null ||
      availableVersions == null ||
      currentVersion == null
    ) {
      return result
    }

    const today = new Date()
    Object.entries(truncatedAgentsUpgradeDueDate).forEach(([dueDate, count]) => {
      if (dueDate === UNLIMITED_AGENTS_KEY) {
        active.push([dueDate, count])
        return
      }

      const dueDateObj = parseISO(dueDate)
      if (!isLicenseActive(dueDateObj, effectiveReleaseDate)) {
        inactive.push([dueDateObj, count])
        return
      }

      if (
        (availableVersions.length > 0 &&
          isLicenseNotCompatibleWithVersion(dueDateObj, availableVersions[0])) ||
        !isLicenseActive(dueDateObj, today)
      ) {
        expiring.push([
          dueDateObj,
          count,
          getLastSupportedVersion(dueDateObj, availableVersions, currentVersion),
        ])
        return
      }

      active.push([dueDateObj, count])
    })

    active.sort(licenseComparatorAsc)
    expiring.sort(licenseComparatorAsc)
    inactive.sort(licenseComparatorDesc)

    return result
  }, [
    currentVersion,
    availableVersions,
    effectiveReleaseDate,
    shouldShowAgentLicenses,
    truncatedAgentsUpgradeDueDate,
  ])

  return {
    readOnly,
    teamLink,
    licenseId,
    licenseMode,
    originalLicenseMode,
    licensedAgentsCount,
    licensedBuildTypesCount,
    licensedPipelinesCount,
    currentDisplayVersion,
    effectiveReleaseDate,
    maintenanceDueDate,
    expirationDate,
    isExpired,
    expiringMessage,
    shouldShowExpirationWarning,
    isObsolete,
    isMaintenanceExpired,
    agentLicenses,
    shouldShowAgentLicenses,
    isJWTLicense: jwtLicense != null,
    hasKnownUpgradeVersions,
    isNotCompatibleWithLatestVersion,
    hasExpiringAgentLicenses: agentLicenses.expiring.length > 0,
    isLicenseModeChanged:
      licenseMode != null && originalLicenseMode != null && licenseMode !== originalLicenseMode,
    shouldShowMaintenanceExpirationWarning:
      !isObsolete && (isNotCompatibleWithLatestVersion || isMaintenanceExpired),
  }
}
