import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import plur from 'plur'
import {useState} from 'react'
import type * as React from 'react'

import licensePageApi from '../../../LicensesPage.api'
import {DEFAULT_ALERT_TIMEOUT} from '../../../LicensesPage.consts'
import {getShortenedLicenseKey} from '../../LegacyLicenses.utils'

import styles from './LicenseKeysForm.module.css'

import {noop} from 'src/utils/empty'

type Props = {
  onClose?: () => void
}
function LicenseKeysForm({onClose}: Props) {
  const [keys, setKeys] = useState('')
  const [addOfflineKeys, {isLoading}] = licensePageApi.endpoints.addOfflineKeys.useMutation()

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault()
    const offlineKeys = keys.split('\n').map(key => key.trim())

    addOfflineKeys(offlineKeys)
      .unwrap()
      .then(({validKeys, invalidKeys}) => {
        if (validKeys.length === 0 && invalidKeys.length === 0) {
          alertService.error('No licenses found', DEFAULT_ALERT_TIMEOUT)
          return
        }

        if (validKeys.length > 0) {
          alertService.successMessage(
            <>
              {`Successfully added license ${plur('key', validKeys.length)}:`}
              {validKeys.map(key => (
                <div key={key}>{getShortenedLicenseKey(key)}</div>
              ))}
            </>,
            DEFAULT_ALERT_TIMEOUT * 2,
          )

          if (invalidKeys.length === 0) {
            onClose?.()
            return
          }

          setKeys(prevState =>
            prevState
              .split('\n')
              .filter(key => !validKeys.includes(key))
              .join('\n'),
          )
        }

        invalidKeys.forEach(([key, reason]) =>
          alertService.error(
            <div>{`Failed to add license key ${getShortenedLicenseKey(key)}: ${reason}`}</div>,
            DEFAULT_ALERT_TIMEOUT * 2,
          ),
        )
      }, noop)
  }

  return (
    <ControlsHeightContext.Provider value={ControlsHeight.M}>
      <form className={styles.form} onSubmit={handleSubmit}>
        <div>{'Please enter license keys below (place each license key on a separate line):'}</div>
        <Input
          inputClassName={styles.input}
          value={keys}
          size={Size.AUTO}
          onChange={e => setKeys(e.target.value)}
          autoFocus
          multiline
        />
        <ButtonSet>
          <Button type="submit" loader={isLoading} disabled={keys.trim().length === 0} primary>
            {'Save'}
          </Button>
          <Button onClick={onClose}>{'Cancel'}</Button>
        </ButtonSet>
      </form>
    </ControlsHeightContext.Provider>
  )
}

export default LicenseKeysForm
