import Button from '@jetbrains/ring-ui-built/components/button/button'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {usePreloadedQuery} from 'react-relay'
import type {PreloadedQuery} from 'react-relay/relay-hooks/EntryPointTypes'

import licensesPageApi from '../LicensesPage.api'
import {useLicenseMaintenance} from '../LicensesPage.hooks'

import type {LicenseActivationHasOfflineKeysQuery} from './__generated__/LicenseActivationHasOfflineKeysQuery.graphql'
import ActivationForm from './ActivationForm/ActivationForm'
import {MANAGE_LICENSE_DOC_LINK} from './LicenseActivation.consts'
import {useLicenseDataPolling} from './LicenseActivation.hooks'
import {hasOfflineKeysQuery} from './LicenseActivation.queries'

import styles from './LicenseActivation.module.css'

import Alert, {AlertType} from 'src/components/common/Alert/Alert'
import {useBooleanQueryParamState} from 'src/hooks/routes'

type Props = {
  hasOfflineKeysQueryRef: PreloadedQuery<LicenseActivationHasOfflineKeysQuery>
}

function LicenseActivation({hasOfflineKeysQueryRef}: Props) {
  const {licensingData} = usePreloadedQuery(hasOfflineKeysQuery, hasOfflineKeysQueryRef)
  const hasOfflineKeys =
    licensingData?.licenseKeys?.count != null && licensingData.licenseKeys.count > 0
  const {isJWTLicense, validateError, updateError, teamLink, activationLink} =
    licensesPageApi.endpoints.getLicenseData.useQueryState(undefined, {
      selectFromResult: ({data}) => ({
        isJWTLicense: data?.jwtLicense != null,
        updateError: data?.lastUpdateError,
        teamLink: data?.teamLink,
        activationLink: data?.activationLink,
        validateError: data?.jwtLicense?.validateError,
      }),
    })
  const {isObsolete, obsoleteLicenseMessage} = useLicenseMaintenance()
  const isValidationError = validateError != null || isObsolete

  const [linkAgents] = licensesPageApi.endpoints.linkAgents.useMutation()

  const [isActivating, setIsActivating] = useBooleanQueryParamState('activating')
  const [isManualRefresh, setIsManualRefresh] = useBooleanQueryParamState('manualRefresh')

  const [startLicenseDataPolling, stopLicenseDataPolling] = useLicenseDataPolling()
  const activationHandler = () => {
    linkAgents()
    startLicenseDataPolling()
  }
  const manualActivationHandler = () => {
    stopLicenseDataPolling()
    setIsActivating(true)
  }

  if (isJWTLicense && updateError == null && !isValidationError) {
    return null
  }

  return isJWTLicense && updateError != null && !isValidationError ? (
    <>
      <Alert type={AlertType.ERROR} contentClassName={styles.message}>
        {`${updateError}. If you need to activate or update a license, get a server license key from your JetBrains Account and go back to this page to paste it.`}
        {!isManualRefresh && (
          <Button
            className={classNames(styles.button, styles.enterKey)}
            onClick={() => setIsManualRefresh(true)}
            inline
          >
            {'Enter your license key'}
          </Button>
        )}
      </Alert>
      {isManualRefresh && <ActivationForm refreshMode />}
    </>
  ) : isActivating ? (
    <ActivationForm />
  ) : (
    <Alert
      type={isValidationError ? AlertType.ERROR : AlertType.INFO}
      contentClassName={styles.message}
    >
      {isValidationError ? (
        isObsolete ? (
          <div>
            <H3 className={styles.title}>{'TeamCity server is running in Professional mode'}</H3>
            {obsoleteLicenseMessage}
          </div>
        ) : (
          `${validateError}. Please click "Get license key" to open your account details, copy a
          valid TeamCity key or get it manually from your JetBrains Account and click
          "I already have a key" to paste it.`
        )
      ) : (
        <div>
          {hasOfflineKeys
            ? `Starting from version 2024.07, TeamCity transitions to a JetBrains Account-based
          license management solution. Your current standalone product keys will still function,
          but we recommend switching to a JetBrains Account license for timely security email
          notifications and automatic license/purchase information updates. Click "Get license key"
          to access your license key via the JetBrains Account. `
            : `Activating a TeamCity license enables you to receive critical security updates via
          email and (for non-Professional licenses) removes free-tier agent and build configuration
          limitations. Click "Get license key" to log into your JetBrains Account and view your
          license key or purchase a new one. `}
          <IconButton
            className={classNames(styles.button, styles.readMore)}
            href={MANAGE_LICENSE_DOC_LINK}
            icon="help"
            target="_blank"
            rel="noreferrer"
            primary
          >
            {'Read more'}
          </IconButton>
        </div>
      )}
      <IconButton
        className={classNames(styles.button, styles.getLicense)}
        href={isObsolete ? teamLink! : activationLink!}
        icon="new-window"
        target="_blank"
        rel="noreferrer"
        onClick={isValidationError ? undefined : activationHandler}
        withBorder
        primary
      >
        {isObsolete ? 'Go to renewal' : 'Get license key'}
      </IconButton>
      <Button className={styles.button} onClick={manualActivationHandler}>
        {'I already have a key'}
      </Button>
    </Alert>
  )
}

export default LicenseActivation
