import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonSet from '@jetbrains/ring-ui-built/components/button-set/button-set'
import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import Input, {Size} from '@jetbrains/ring-ui-built/components/input/input'
import {useState} from 'react'

import licensesPageApi from '../../LicensesPage.api'

import styles from './ActivationForm.module.css'

import {useBooleanQueryParamState} from 'src/hooks/routes'
import {noop} from 'src/utils/empty'
import {extractError} from 'src/utils/extractError'

type Props = {
  onSubmit?: () => void
  onCancel?: () => void
  refreshMode?: boolean
}
function ActivationForm({onSubmit, onCancel, refreshMode}: Props) {
  const [activateLicense, {error, isLoading}] =
    licensesPageApi.endpoints.activateLicense.useMutation()
  const [value, setValue] = useState('')
  const [_, setIsActivating] = useBooleanQueryParamState(
    refreshMode ? 'manualRefresh' : 'activating',
  )

  return (
    <ControlsHeightContext.Provider value={ControlsHeight.M}>
      <form
        className={styles.form}
        onSubmit={e => {
          e.preventDefault()

          activateLicense(value.trim())
            .unwrap()
            .then(() => setIsActivating(false), noop)
          onSubmit?.()
        }}
      >
        {!refreshMode && (
          <div>
            {
              'Paste the license key copied from your JetBrains Account page and click Activate license.'
            }
          </div>
        )}
        <Input
          inputClassName={styles.input}
          size={Size.AUTO}
          placeholder={'Enter serialized license'}
          error={extractError(error)?.toString()}
          value={value}
          onChange={e => setValue(e.currentTarget.value)}
          autoFocus
          multiline
        />
        <ButtonSet>
          <Button type="submit" loader={isLoading} disabled={value.trim().length === 0} primary>
            {`${refreshMode ? 'Refresh' : 'Activate'} license`}
          </Button>
          <Button
            onClick={() => {
              setIsActivating(false)
              onCancel?.()
            }}
          >
            {'Cancel'}
          </Button>
        </ButtonSet>
      </form>
    </ControlsHeightContext.Provider>
  )
}

export default ActivationForm
