import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {format} from 'date-fns'
import plur from 'plur'

import {DATE_FORMAT, UNLIMITED_AGENTS_KEY} from '../../../LicensesPage.consts'
import type {
  ActiveAgentLicenses,
  ExpiringAgentLicenses,
  InactiveAgentLicenses,
} from '../../LicenseInformation.types'

import styles from './AgentsLicensesTable.module.css'

type Props = {
  title: string
  agentLicenses: ActiveAgentLicenses | ExpiringAgentLicenses | InactiveAgentLicenses
  withSupportedVersions?: boolean
  inactive?: boolean
}
function AgentsLicensesTable({title, agentLicenses, withSupportedVersions, inactive}: Props) {
  return (
    <div>
      <div
        className={classNames(styles.grid, styles.header, {
          [styles.withVersions]: withSupportedVersions,
        })}
      >
        <span>{'Number of authorized agents'}</span>
        <span>{'End of maintenance'}</span>
        {withSupportedVersions && <span>{'Latest supported TeamCity release'}</span>}
      </div>
      <div
        className={classNames(styles.grid, styles.table, {
          [styles.withVersions]: withSupportedVersions,
          [styles.inactive]: inactive,
        })}
      >
        <span className={styles.heading}>{title}</span>
        {agentLicenses.map(([dueDate, count, lastSupportedVersion]) => {
          const isUnlimited = dueDate === UNLIMITED_AGENTS_KEY
          const dueDateStr = isUnlimited ? 'Unlimited' : format(dueDate, DATE_FORMAT)

          return (
            <div key={dueDateStr} className={styles.row}>
              <span>{`${count} ${plur('agent', count)}`}</span>
              <span>
                {withSupportedVersions && <SvgIcon className={styles.icon} icon={'warning'} />}
                {dueDateStr}
              </span>
              {withSupportedVersions && !isUnlimited && <span>{lastSupportedVersion}</span>}
            </div>
          )
        })}
      </div>
    </div>
  )
}

export default AgentsLicensesTable
