import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {useState} from 'react'

import type {InactiveAgentLicenses} from '../../LicenseInformation.types'
import AgentsLicensesTable from '../AgentsLicensesTable/AgentsLicensesTable'

import styles from './InactiveAgentsLicenses.module.css'

type Props = {
  agentLicenses: InactiveAgentLicenses
}

function InactiveAgentsLicenses({agentLicenses}: Props) {
  const [isExpanded, setIsExpanded] = useState(false)

  return (
    <div>
      <IconButton
        className={styles.toggle}
        iconClassName={styles.icon}
        icon={isExpanded ? 'chevron-down' : 'chevron-right'}
        onClick={() => setIsExpanded(prevState => !prevState)}
        childrenLeft
      >
        {'Show inactive licenses'}
      </IconButton>
      {isExpanded && (
        <AgentsLicensesTable title={'Inactive licenses'} agentLicenses={agentLicenses} inactive />
      )}
    </div>
  )
}

export default InactiveAgentsLicenses
