import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {IconButton, SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {formatDistanceToNow} from 'date-fns'
import {useState, memo} from 'react'

import licensesPageApi from '../../LicensesPage.api'
import {NO_LAST_UPDATE_VALUE, DEFAULT_ALERT_TIMEOUT} from '../../LicensesPage.consts'

import styles from './LicenseActions.module.css'

import Badge from 'src/components/common/Badge/Badge'
import ConfirmationDialog from 'src/components/common/ConfirmationDialog/ConfirmationDialog'
import {useBooleanQueryParamState} from 'src/hooks/routes'
import {extractError} from 'src/utils/extractError'

function LicenseActions() {
  const {deactivationLink, lastUpdateTime, isUpdateError} =
    licensesPageApi.endpoints.getLicenseData.useQueryState(undefined, {
      selectFromResult: ({data}) => ({
        deactivationLink: data?.deactivationLink,
        lastUpdateTime: data?.lastUpdateTime,
        isUpdateError: data?.lastUpdateError != null,
      }),
    })

  const [isShown, setIsShown] = useState(false)
  const [_, setManualRefresh] = useBooleanQueryParamState('manualRefresh')

  const [refreshLicense, {isLoading: isRefreshing}] =
    licensesPageApi.endpoints.refreshLicense.useMutation()
  const [deactivateLicense, {isLoading: isDeactivating}] =
    licensesPageApi.endpoints.deactivateLicense.useMutation()

  return (
    <Badge
      label={
        <span className={classNames(isUpdateError && styles.error)}>
          {isUpdateError && <SvgIcon icon={'exception'} />}
          {`Last${isUpdateError ? ' successful ' : ' '}update: ${
            lastUpdateTime != null && lastUpdateTime !== NO_LAST_UPDATE_VALUE
              ? formatDistanceToNow(lastUpdateTime, {addSuffix: true})
              : 'never'
          }`}
        </span>
      }
    >
      <div className={styles.content}>
        <IconButton
          className={styles.button}
          icon="update"
          loader={isRefreshing}
          primary
          onClick={() =>
            refreshLicense()
              .unwrap()
              .then(() =>
                alertService.successMessage(
                  'Successfully updated license data',
                  DEFAULT_ALERT_TIMEOUT,
                ),
              )
              .catch(() => {
                setManualRefresh(true)
              })
          }
        >
          {'Refresh'}
        </IconButton>
        <Button
          className={classNames(styles.button, styles.deactivate)}
          onClick={() => setIsShown(true)}
          inline
        >
          {'Deactivate'}
        </Button>
      </div>
      <ConfirmationDialog
        contentClassName={styles.deactivationDialog}
        show={isShown}
        title={'Deactivate your TeamCity license?'}
        controlsHeightValue={ControlsHeight.M}
        loader={isDeactivating}
        onConfirm={() => {
          deactivateLicense()
            .unwrap()
            .then(() => setIsShown(false))
            .catch(err => alertService.error(extractError(err)?.toString(), DEFAULT_ALERT_TIMEOUT))
        }}
        onCancel={() => setIsShown(false)}
      >
        <div className={styles.deactivationWarning}>
          <span>
            {'You are removing your TeamCity license from the TeamCity server. '}
            {'To unlink the license from your server ID, please additionally click '}
            <IconButton
              className={classNames(styles.button, styles.deactivationLink)}
              href={deactivationLink!}
              icon="new-window"
              target="_blank"
              rel="noreferrer"
              primary
            >
              {'Deactivate license'}
            </IconButton>
            {' in the corresponding JetBrains account.'}
          </span>
          <span>
            {'You will no longer receive vital notifications ' +
              'from JetBrains (for example, major security updates). You can re-activate your ' +
              'license key at any time in the future.'}
          </span>
          <span>
            {'Please type '}
            <strong>{location.host}</strong>
            {' to confirm.'}
          </span>
        </div>
      </ConfirmationDialog>
    </Badge>
  )
}

export default memo(LicenseActions)
