import {compareAsc} from 'date-fns'
import type {ChangeEvent} from 'react'
import {useCallback, useState, useMemo} from 'react'

import licensesPageApi from '../LicensesPage.api'
import type {
  AvailableVersion,
  LegacyLicenseData,
  LegacyLicenseDataWithNotCompatibleVersions,
} from '../LicensesPage.types'
import {getNotCompatibleVersions} from '../LicensesPage.utils'

import {emptyArray} from 'src/utils/empty'

function getComparator(useAscMaintenance = true) {
  return (l1: LegacyLicenseData, l2: LegacyLicenseData) => {
    if (l1.expirationDate != null) {
      return l2.expirationDate != null ? compareAsc(l2.expirationDate, l1.expirationDate) : -1
    }
    return useAscMaintenance
      ? compareAsc(l1.maintenanceDueDate, l2.maintenanceDueDate)
      : compareAsc(l2.maintenanceDueDate, l1.maintenanceDueDate)
  }
}

export function useOfflineKeys() {
  const {data: licenses} = licensesPageApi.endpoints.getOfflineKeys.useQuery()
  const {availableVersions, readOnlyMode} = licensesPageApi.endpoints.getLicenseData.useQueryState(
    undefined,
    {
      selectFromResult: ({data}) => ({
        readOnlyMode: data?.readOnly,
        availableVersions: data?.availableVersions ?? (emptyArray as AvailableVersion[]),
      }),
    },
  )

  const [activeLicenses, inactiveLicenses, allNotCompatibleVersions] = useMemo(() => {
    const allNotCompatibleVersions = new Set<AvailableVersion>()
    const active = [] as LegacyLicenseDataWithNotCompatibleVersions[]
    const inactive = [] as LegacyLicenseData[]

    licenses?.forEach(license => {
      if (!license.active) {
        inactive.push(license)
        return
      }

      const notCompatibleVersions = getNotCompatibleVersions(
        license.maintenanceDueDate,
        availableVersions,
      )
      notCompatibleVersions.forEach(version => allNotCompatibleVersions.add(version))

      active.push({
        ...license,
        notCompatibleVersions,
      })
    })

    active.sort(getComparator())
    inactive.sort(getComparator(false))

    return [active, inactive, allNotCompatibleVersions]
  }, [licenses, availableVersions])

  return {activeLicenses, inactiveLicenses, allNotCompatibleVersions, readOnlyMode}
}

export function useLicenseKeysSelection(licenses: LegacyLicenseData[]) {
  const [selectedKeys, setSelectedKeys] = useState<Set<string>>(new Set())

  const toggleSelectKey = useCallback((e: ChangeEvent<HTMLInputElement>) => {
    setSelectedKeys(prevSelected => {
      if (e.target.checked) {
        prevSelected.add(e.target.value)
      } else {
        prevSelected.delete(e.target.value)
      }

      return new Set(prevSelected)
    })
  }, [])

  const toggleSelectAllKeys = (e: ChangeEvent<HTMLInputElement>) => {
    setSelectedKeys(
      e.currentTarget.checked ? new Set(licenses.map(license => license.key)) : new Set(),
    )
  }

  const clearSelectedKeys = () => {
    setSelectedKeys(new Set())
  }

  return {
    selectedKeys,
    toggleSelectKey,
    clearSelectedKeys,
    toggleSelectAllKeys,
  }
}
