import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import {format} from 'date-fns'
import type {ChangeEventHandler} from 'react'
import {memo} from 'react'

import {LEGACY_LICENSE_DATE_FORMAT} from '../../LicensesPage.consts'
import type {LegacyLicenseDataWithNotCompatibleVersions} from '../../LicensesPage.types'
import {getEntityLicensesCount} from '../../LicensesPage.utils'
import WarningIcon from '../../WarningIcon/WarningIcon'
import HiddenLicenseKey from '../HiddenLicenseKey/HiddenLicenseKey'

import styles from './ActiveLegacyLicenses.module.css'

type Props = {
  license: LegacyLicenseDataWithNotCompatibleVersions
  checked?: boolean
  readOnly?: boolean
  onSelect?: ChangeEventHandler<HTMLInputElement>
}
function ActiveLegacyLicense({license, checked, readOnly, onSelect}: Props) {
  const generationDate = format(license.generationDate, LEGACY_LICENSE_DATE_FORMAT)
  const maintenanceDueDate = format(license.maintenanceDueDate, LEGACY_LICENSE_DATE_FORMAT)
  const expirationDate =
    license.expirationDate != null
      ? format(license.expirationDate, LEGACY_LICENSE_DATE_FORMAT)
      : 'N/A'

  return (
    <tr>
      <td>
        <HiddenLicenseKey licenseKey={license.key} />
      </td>
      <td>{license.type}</td>
      <td>{getEntityLicensesCount(license.agentsCount)}</td>
      <td>{getEntityLicensesCount(license.buildTypesCount)}</td>
      <td>{getEntityLicensesCount(license.pipelinesCount)}</td>
      <td>{generationDate}</td>
      <td>
        {(license.notCompatibleVersions.length > 0 ||
          license.maintenanceExpired ||
          license.maintenanceExpiringSoon) && (
          <WarningIcon
            className={styles.icon}
            severity={'warning'}
            title={
              license.notCompatibleVersions.length > 0
                ? `The license needs renewing before upgrade to ${license.notCompatibleVersions
                    .map(({version}) => version)
                    .join(', ')}`
                : `Maintenance is ${license.maintenanceExpired ? 'expired' : 'expiring soon'}`
            }
          />
        )}
        {maintenanceDueDate}
      </td>
      <td>
        {license.expiringSoon && (
          <WarningIcon
            className={styles.icon}
            severity={'error'}
            title={'License is expiring soon'}
          />
        )}
        {expirationDate}
      </td>
      {!readOnly && (
        <td>
          <Checkbox
            containerClassName={styles.checkbox}
            checked={checked}
            value={license.key}
            onChange={onSelect}
            aria-label="Select license key"
          />
        </td>
      )}
    </tr>
  )
}

export default memo(ActiveLegacyLicense)
