import licensesPageApi from '../../LicensesPage.api'
import {ENTITY_UNLIMITED_COUNT} from '../../LicensesPage.consts'

export function useAgentsLicensesInformation() {
  const {teamLink, areAgentsUnlimited} = licensesPageApi.endpoints.getLicenseData.useQueryState(
    undefined,
    {
      selectFromResult: ({data}) => ({
        teamLink: data?.teamLink,
        areAgentsUnlimited: data?.licensedAgentsCount === ENTITY_UNLIMITED_COUNT,
      }),
    },
  )

  return {teamLink, areAgentsUnlimited}
}
