import {subDays} from 'date-fns'

import {ENTITY_UNLIMITED_COUNT} from './LicensesPage.consts'
import type {AvailableVersion} from './LicensesPage.types'

export function getEntityLicensesCount(entity?: number) {
  return entity === ENTITY_UNLIMITED_COUNT ? 'Unlimited' : entity
}

export function isLicenseActive(dueDate: Date | number, releaseDate: Date | number) {
  return !(dueDate < subDays(releaseDate, 1))
}

export function getLastSupportedVersion(
  dueDate: Date | number,
  releases: AvailableVersion[],
  currentVersion: string,
) {
  let lastVersion = currentVersion
  for (const {version, releaseDate} of releases) {
    if (isLicenseActive(dueDate, releaseDate)) {
      lastVersion = version
      break
    }
  }

  return lastVersion
}

export function isLicenseNotCompatibleWithVersion(
  dueDate: Date | number,
  release: AvailableVersion,
) {
  return !isLicenseActive(dueDate, release.releaseDate)
}

export function getNotCompatibleVersions(dueDate: Date | number, releases: AvailableVersion[]) {
  return releases.filter(({releaseDate}) => !isLicenseActive(dueDate, releaseDate))
}
