import classNames from 'classnames'
import {useMemo, useState} from 'react'

import {getHiddenLicenseKey} from '../LegacyLicenses.utils'

import styles from './HiddenLicenseKey.module.css'

type Props = {
  licenseKey: string
}
function HiddenLicenseKey({licenseKey}: Props) {
  const hiddenKey = useMemo(() => getHiddenLicenseKey(licenseKey), [licenseKey])
  const [isFullKeyVisible, setIsFullKeyVisible] = useState(false)

  return (
    <div
      role={'button'}
      tabIndex={0}
      className={styles.container}
      title={`${isFullKeyVisible ? 'Hide' : 'Show'} license key`}
      onKeyDown={e => {
        if (e.key === 'Enter') {
          setIsFullKeyVisible(prevState => !prevState)
        }
      }}
      onClick={() => {
        const selection = window.getSelection()
        if (selection != null && selection.toString().length > 0) {
          return
        }
        setIsFullKeyVisible(prevState => !prevState)
      }}
    >
      <span
        className={classNames(
          {[styles.hidden]: isFullKeyVisible},
          styles.secret,
          isFullKeyVisible ? styles.out : styles.in,
        )}
      >
        {hiddenKey}
      </span>
      <span
        className={classNames(
          {[styles.hidden]: !isFullKeyVisible},
          isFullKeyVisible ? styles.in : styles.out,
        )}
      >
        {licenseKey}
      </span>
    </div>
  )
}

export default HiddenLicenseKey
