import type {EntryPointProps} from 'react-relay'

import LegacyLicenses from './LegacyLicenses/LegacyLicenses'
import type {LicenseActivationHasOfflineKeysQuery} from './LicenseActivation/__generated__/LicenseActivationHasOfflineKeysQuery.graphql'
import LicenseActivation from './LicenseActivation/LicenseActivation'
import LicenseInformation from './LicenseInformation/LicenseInformation'
import licensesPageApi from './LicensesPage.api'
import TrueUpLicenseStatistics from './TrueUpLicenseStatistics/TrueUpLicenseStatistics'

import styles from './LicensesPage.module.css'

import Loader from 'src/components/common/Loader/Loader'

type Queries = {
  hasOfflineKeys: LicenseActivationHasOfflineKeysQuery
}

function LicensesPage({queries}: EntryPointProps<Queries, {}, {}, {}>) {
  const {isJWTLicense, isLoading, readOnly} = licensesPageApi.endpoints.getLicenseData.useQuery(
    undefined,
    {
      selectFromResult: ({data}) => ({
        isLoading: data == null,
        readOnly: data?.readOnly,
        isJWTLicense: data?.jwtLicense != null,
      }),
    },
  )

  if (isLoading) {
    return <Loader />
  }

  return (
    <div className={styles.page}>
      {!readOnly && <LicenseActivation hasOfflineKeysQueryRef={queries.hasOfflineKeys} />}
      <LicenseInformation />
      <TrueUpLicenseStatistics />
      {!isJWTLicense && <LegacyLicenses />}
    </div>
  )
}

export default LicensesPage
export type LicensesPageComponent = typeof LicensesPage
