import Link from '@jetbrains/ring-ui-built/components/link/link'

import {UPDATES_PAGE_LINK} from './LicenseInformation.consts'

const latestVersionLink = <Link href={UPDATES_PAGE_LINK}>{'the latest version'}</Link>

export function getMaintenanceExpirationText(
  hasExpiringAgentLicenses: boolean,
  hasKnownUpgradeVersions: boolean,
) {
  if (hasExpiringAgentLicenses) {
    return (
      <div>
        {hasKnownUpgradeVersions ? (
          <>
            {'Server and agent licenses that display the warning icon do not support '}
            {latestVersionLink}
            {' of TeamCity server. Installing this update'}
          </>
        ) : (
          'The maintenance period for server and agent licenses has ended. Updating your server to newer major TeamCity releases'
        )}
        {' will disable these licenses, reducing the number of build agents and applying Professional tier limitations to your server.' +
          ' Renew the licenses to maintain your agent count and unlimited build configurations while benefiting from the latest server updates.'}
      </div>
    )
  }

  return (
    <div>
      {hasKnownUpgradeVersions ? (
        <>
          {'This server license does not support '}
          {latestVersionLink}
          {' of TeamCity server. Installing this update'}
        </>
      ) : (
        'The maintenance period for this server license has ended. Updating your server to newer major TeamCity releases'
      )}
      {' will nullify your current license and apply the free TeamCity Professional license instead (limited to 100 active build configurations).' +
        ' Renew the server license to keep using it while benefiting from the latest server updates.'}
    </div>
  )
}
