import {useEffect, useState, useRef} from 'react'

import licensesPageApi from '../LicensesPage.api'

import {MAX_POLL_COUNT, POLLING_INTERVAL} from './LicenseActivation.consts'

import {useBooleanQueryParamState} from 'src/hooks/routes'

export function useLicenseDataPolling() {
  const count = useRef(0)
  const [_, setIsActivating] = useBooleanQueryParamState('activating')
  const [isPollingActive, setIsPollingActive] = useState(false)

  const {isKeyDataLoaded, fulfilledTimeStamp} = licensesPageApi.endpoints.getLicenseData.useQuery(
    undefined,
    {
      refetchOnFocus: true,
      pollingInterval: isPollingActive ? POLLING_INTERVAL : 0,
      skipPollingIfUnfocused: true,
      selectFromResult: ({data, fulfilledTimeStamp}) => ({
        fulfilledTimeStamp,
        isKeyDataLoaded: data?.jwtLicense?.keyData != null,
      }),
    },
  )

  const startPolling = () => {
    setIsPollingActive(true)
    count.current = 0
  }
  const stopPolling = () => setIsPollingActive(false)

  useEffect(() => {
    if (!isPollingActive) {
      return
    }

    if (isKeyDataLoaded || count.current === MAX_POLL_COUNT) {
      stopPolling()

      if (isKeyDataLoaded) {
        setIsActivating(false)
      }
    }
    count.current++
  }, [isPollingActive, isKeyDataLoaded, fulfilledTimeStamp, setIsActivating])

  return [startPolling, stopPolling]
}
