import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import {format} from 'date-fns'
import type {ChangeEventHandler} from 'react'
import {memo} from 'react'

import {LEGACY_LICENSE_DATE_FORMAT} from '../../LicensesPage.consts'
import type {LegacyLicenseData} from '../../LicensesPage.types'
import HiddenLicenseKey from '../HiddenLicenseKey/HiddenLicenseKey'

import styles from './InactiveLegacyLicenses.module.css'

type Props = {
  license: LegacyLicenseData
  checked?: boolean
  readOnly?: boolean
  onSelect?: ChangeEventHandler<HTMLInputElement>
}
function InactiveLegacyLicense({license, checked, readOnly, onSelect}: Props) {
  const maintenanceDueDate = format(license.maintenanceDueDate, LEGACY_LICENSE_DATE_FORMAT)
  const expirationDate =
    license.expirationDate != null
      ? format(license.expirationDate, LEGACY_LICENSE_DATE_FORMAT)
      : null

  return (
    <tr>
      <td>
        <HiddenLicenseKey licenseKey={license.key} />
      </td>
      <td>
        <strong>{license.type}</strong>
        {expirationDate != null
          ? `, expires: ${expirationDate}`
          : `, end of maintenance: ${maintenanceDueDate}`}
        {license.expired && (
          <>
            {' ('}
            <span className={styles.warn}>{'expired'}</span>
            {')'}
          </>
        )}
        {license.obsolete && (
          <>
            {' ('}
            <span className={styles.warn}>{'obsolete'}</span>
            {')'}
          </>
        )}
      </td>
      {!readOnly && (
        <td>
          <Checkbox
            containerClassName={styles.checkbox}
            checked={checked}
            value={license.key}
            onChange={onSelect}
          />
        </td>
      )}
    </tr>
  )
}

export default memo(InactiveLegacyLicense)
