import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Radio from '@jetbrains/ring-ui-built/components/radio/radio'
import classNames from 'classnames'
import {format} from 'date-fns'

import {useQueryParamState} from '../../../../../hooks/routes'
import {LEGACY_LICENSE_DATE_FORMAT} from '../../LicensesPage.consts'
import type {
  AvailableVersion,
  LegacyLicenseDataWithNotCompatibleVersions,
} from '../../LicensesPage.types'
import {useLicenseKeysSelection} from '../LegacyLicenses.hooks'
import LegacyLicensesActions from '../LegacyLicensesActions/LegacyLicensesActions'

import ActiveLegacyLicense from './ActiveLegacyLicense'

import styles from './ActiveLegacyLicenses.module.css'

import Alert, {AlertType} from 'src/components/common/Alert/Alert'

type Props = {
  licenses: LegacyLicenseDataWithNotCompatibleVersions[]
  allIncompatibleVersions: Set<AvailableVersion>
  readOnly?: boolean
}
function ActiveLegacyLicenses({licenses, allIncompatibleVersions, readOnly}: Props) {
  const {selectedKeys, clearSelectedKeys, toggleSelectKey, toggleSelectAllKeys} =
    useLicenseKeysSelection(licenses)

  const [notCompatibleVersion, setNotCompatibleVersion] = useQueryParamState(
    'notCompatibleWith',
    '',
  )

  return (
    <div className={styles.activeKeys}>
      <H2 className={styles.heading}>{'Active license keys'}</H2>
      {allIncompatibleVersions.size > 0 && (
        <Alert type={AlertType.WARNING}>
          <div>{`New TeamCity version is available, maintenance period of some licenses does not cover
          the new version release date and the licenses require renewal before the upgrade.`}</div>
          <div className={styles.show}>{'Show:'}</div>
          <Radio onChange={(value: string) => setNotCompatibleVersion(value)}>
            <Radio.Item value={''} checked={notCompatibleVersion === ''}>
              {'all licenses'}
            </Radio.Item>
            {Array.from(allIncompatibleVersions).map(incompatibleVersion => (
              <Radio.Item
                key={incompatibleVersion.version}
                value={incompatibleVersion.version}
                checked={incompatibleVersion.version === notCompatibleVersion}
              >{`incompatible with TeamCity ${incompatibleVersion.version}, effective release date ${format(incompatibleVersion.releaseDate, LEGACY_LICENSE_DATE_FORMAT)}`}</Radio.Item>
            ))}
          </Radio>
        </Alert>
      )}
      <table className={classNames(styles.licenseKeysTable, {[styles.readOnly]: readOnly})}>
        <thead>
          <tr>
            <th>{'License key'}</th>
            <th>{'Type'}</th>
            <th>{'# of agents'}</th>
            <th>{'# of build configurations'}</th>
            <th>{'# of pipelines'}</th>
            <th>{'Generation date'}</th>
            <th>{'End of maintenance'}</th>
            <th>{'Expiration Date'}</th>
            {!readOnly && (
              <th>
                <Checkbox
                  containerClassName={styles.checkbox}
                  checked={selectedKeys.size === licenses.length}
                  onChange={toggleSelectAllKeys}
                  aria-label="Select all license keys"
                />
              </th>
            )}
          </tr>
        </thead>
        <tbody>
          {licenses.map(license => {
            if (
              notCompatibleVersion !== '' &&
              !license.notCompatibleVersions.some(
                release => release.version === notCompatibleVersion,
              )
            ) {
              return null
            }

            return (
              <ActiveLegacyLicense
                key={license.key}
                license={license}
                onSelect={toggleSelectKey}
                readOnly={readOnly}
                checked={selectedKeys.has(license.key)}
              />
            )
          })}
        </tbody>
      </table>
      <LegacyLicensesActions
        selectedKeys={selectedKeys}
        onRemovalSuccess={clearSelectedKeys}
        readOnly={readOnly}
      />
    </div>
  )
}

export default ActiveLegacyLicenses
