import type {LicenseData, LegacyLicenseData} from './LicensesPage.types'

import {restBaseApi} from 'src/services/restBase'

const prefix = 'app/license'

const enhancedRestBaseApi = restBaseApi.enhanceEndpoints({
  addTagTypes: ['License', 'OfflineKeys', 'TrueUpStatistics'],
})

const licensesPageApi = enhancedRestBaseApi.injectEndpoints({
  endpoints: build => ({
    getLicenseData: build.query<LicenseData, void>({
      query: _ => ({
        url: `${prefix}/licenseData`,
      }),
      providesTags: ['License'],
    }),
    refreshLicense: build.mutation<undefined, void>({
      query: _ => ({
        url: `${prefix}/refreshLicense`,
        method: 'POST',
      }),
      invalidatesTags: ['License', 'TrueUpStatistics'],
    }),
    deactivateLicense: build.mutation<undefined, void>({
      query: _ => ({
        url: `${prefix}/deleteJwtLicense`,
        method: 'DELETE',
      }),
      invalidatesTags: ['License', 'TrueUpStatistics'],
    }),
    activateLicense: build.mutation<undefined, string>({
      query: jwtLicense => ({
        url: `${prefix}/activateLicense`,
        body: jwtLicense,
        method: 'POST',
      }),
      invalidatesTags: ['License', 'TrueUpStatistics'],
    }),
    linkAgents: build.mutation<undefined, void>({
      query: () => ({
        url: `${prefix}/linkAgents`,
        method: 'POST',
      }),
    }),
    getOfflineKeys: build.query<LegacyLicenseData[], void>({
      query: _ => ({
        url: `${prefix}/offlineKeys`,
      }),
      providesTags: ['OfflineKeys'],
    }),
    getHashedOfflineKeys: build.query<string[], void>({
      query: _ => ({
        url: `${prefix}/hashedOfflineKeys`,
      }),
      providesTags: ['OfflineKeys'],
    }),
    addOfflineKeys: build.mutation<AddOfflineKeysResponse, string[]>({
      query: offlineKeys => {
        const body = new FormData()
        body.append('licenseKeys', offlineKeys.join('\n'))
        body.append('enterKeys', 'true')
        body.append('submitKeys', 'Save')

        return {
          url: '/admin/licenses.html',
          body,
          method: 'POST',
          responseHandler: 'text',
        }
      },
      transformResponse: (text: string) => {
        const xml = new DOMParser().parseFromString(text, 'text/xml')

        const allKeys = xml.querySelectorAll('licenseKey')
        const validKeys = [] as AddOfflineKeysResponse['validKeys']
        const invalidKeys = [] as AddOfflineKeysResponse['invalidKeys']

        allKeys.forEach(key => {
          const strKey = key.querySelector('key')!.textContent!

          if (key.getAttribute('valid') === 'true') {
            validKeys.push(strKey)
            return
          }

          const invalidReason = key.querySelector('invalidReason')!.textContent!
          invalidKeys.push([strKey, invalidReason])
        })

        return {
          validKeys,
          invalidKeys,
        }
      },
      invalidatesTags: res =>
        res != null && res.validKeys.length > 0
          ? ['OfflineKeys', 'License', 'TrueUpStatistics']
          : [],
    }),
    deleteOfflineKeys: build.mutation<undefined, string[]>({
      query: offlineKeys => {
        const body = new FormData()
        body.append('removeKey', offlineKeys.join(':'))

        return {
          url: `/admin/licenses.html`,
          body,
          method: 'POST',
        }
      },
      invalidatesTags: ['OfflineKeys', 'License', 'TrueUpStatistics'],
    }),
    getTrueUpStatisticsHTML: build.query<string, void>({
      query: () => ({
        url: '/admin/perUsageLicenseDataController.html',
      }),
      providesTags: ['TrueUpStatistics'],
    }),
  }),
})

type AddOfflineKeysResponse = {
  validKeys: string[]
  invalidKeys: Array<string[]>
}

export default licensesPageApi
