import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {memo} from 'react'

import styles from './WarningIcon.module.css'

type Props = {
  className?: string
  title?: string
  severity?: 'warning' | 'error'
}

function WarningIcon({className, title, severity = 'warning'}: Props) {
  return (
    <Tooltip title={title}>
      <SvgIcon className={classNames(styles[severity], className)} icon={'warning'} />
    </Tooltip>
  )
}

export default memo(WarningIcon)
