import alertService from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import confirm from '@jetbrains/ring-ui-built/components/confirm-service/confirm-service'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {skipToken} from '@reduxjs/toolkit/query'
import plur from 'plur'
import {useState} from 'react'

import licensesPageApi from '../../LicensesPage.api'
import {DEFAULT_ALERT_TIMEOUT} from '../../LicensesPage.consts'
import {getShortenedLicenseKey} from '../LegacyLicenses.utils'

import LicenseKeysForm from './LicenseKeysForm/LicenseKeysForm'

import styles from './LegacyLicensesActions.module.css'

import {downloadFile} from 'src/utils/download'
import {noop} from 'src/utils/empty'
import {extractError} from 'src/utils/extractError'

type Props = {
  selectedKeys: Set<string>
  readOnly?: boolean
  removalOnly?: boolean
  onRemovalSuccess?: () => void
}

function LegacyLicensesActions({selectedKeys, removalOnly, readOnly, onRemovalSuccess}: Props) {
  const [showLicenseKeysForm, setShowLicenseKeysForm] = useState(false)

  const {data: hashedKeys} = licensesPageApi.endpoints.getHashedOfflineKeys.useQuery(
    removalOnly ? skipToken : undefined,
  )
  const [deleteKeys, {isLoading}] = licensesPageApi.endpoints.deleteOfflineKeys.useMutation()

  const handleKeysRemoval = () => {
    const selectedKeysArray = Array.from(selectedKeys)

    confirm({
      text: `Remove selected license ${plur('key', selectedKeys.size)}?`,
    })
      .then(() =>
        deleteKeys(selectedKeysArray)
          .unwrap()
          .then(() => {
            alertService.successMessage(
              <>
                {`Successfully removed license ${plur('key', selectedKeys.size)}:`}
                {selectedKeysArray.map(key => (
                  <div key={key}>{getShortenedLicenseKey(key)}</div>
                ))}
              </>,
              DEFAULT_ALERT_TIMEOUT * 2,
            )
            onRemovalSuccess?.()
          })
          .catch(err => alertService.error(extractError(err)?.toString(), DEFAULT_ALERT_TIMEOUT)),
      )
      .catch(noop)
  }

  return (
    <>
      <div className={styles.actions}>
        {!removalOnly && (
          <>
            {!readOnly && (
              <Button onClick={() => setShowLicenseKeysForm(true)} disabled={showLicenseKeysForm}>
                {'Enter new license key'}
              </Button>
            )}
            <IconButton
              icon={'download'}
              disabled={hashedKeys == null}
              onClick={() =>
                downloadFile(hashedKeys!.join('\n'), 'teamcity-offline-keys.txt', 'text/plain')
              }
            >
              {'Download hashed offline keys'}
            </IconButton>
          </>
        )}
        {!readOnly && (
          <Button
            className={styles.remove}
            onClick={handleKeysRemoval}
            loader={isLoading}
            disabled={selectedKeys.size === 0}
            inline
          >
            {'Remove selected'}
          </Button>
        )}
      </div>
      {showLicenseKeysForm && <LicenseKeysForm onClose={() => setShowLicenseKeysForm(false)} />}
    </>
  )
}

export default LegacyLicensesActions
