import {memo} from 'react'

import ActiveLegacyLicenses from './ActiveLegacyLicenses/ActiveLegacyLicenses'
import InactiveLegacyLicenses from './InactiveLegacyLicenses/InactiveLegacyLicenses'
import {useOfflineKeys} from './LegacyLicenses.hooks'

function LegacyLicenses() {
  const {activeLicenses, inactiveLicenses, allNotCompatibleVersions, readOnlyMode} =
    useOfflineKeys()

  if (activeLicenses.length === 0 && inactiveLicenses.length === 0) {
    return null
  }

  return (
    <>
      {activeLicenses.length > 0 && (
        <ActiveLegacyLicenses
          licenses={activeLicenses}
          allIncompatibleVersions={allNotCompatibleVersions}
          readOnly={readOnlyMode}
        />
      )}
      {inactiveLicenses.length > 0 && (
        <InactiveLegacyLicenses licenses={inactiveLicenses} readOnly={readOnlyMode} />
      )}
    </>
  )
}

export default memo(LegacyLicenses)
