import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'

import licensesPageApi from '../LicensesPage.api'

import styles from './TrueUpLicenseStatistics.module.css'

import {InjectHtml} from 'src/components/common/InjectHtml/InjectHtml'

function TrueUpLicenseStatistics() {
  const {data: trueUpStatistics = ''} = licensesPageApi.endpoints.getTrueUpStatisticsHTML.useQuery()

  if (trueUpStatistics.length === 0) {
    return null
  }

  return (
    <div>
      <H2 className={styles.heading}>{'Server usage data'}</H2>
      <InjectHtml content={trueUpStatistics} showLoader={false} />
    </div>
  )
}

export default TrueUpLicenseStatistics
